import { v4 as uuidv4 } from "uuid";
import { useState, useRef, useEffect } from "react";
import getAverageColor from "./core/getAverageColor";
import getLuminance from "./core/getLuminance";

const ProjectCard = ({ element }) => {
  const [tooltip, setTooltip] = useState(null);
  const imgRef = useRef(null);
  const tooltipRef = useRef(null);
  const pos = useRef({ x: 0, y: 0 });
  const current = useRef({ x: 0, y: 0 });
  const raf = useRef(null);

  useEffect(() => {
    const animate = () => {
      current.current.x += (pos.current.x - current.current.x) * 0.12;
      current.current.y += (pos.current.y - current.current.y) * 0.12;

      if (tooltipRef.current) {
        tooltipRef.current.style.transform = `translate(${current.current.x}px, ${current.current.y}px)`;
      }

      raf.current = requestAnimationFrame(animate);
    };

    raf.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(raf.current);
  }, []);

  const handleMouseEnter = () => {
    try {
      const avg = getAverageColor(imgRef.current);
      const lum = getLuminance(avg);
      const isDark = lum < 0.5;
      setTooltip({
        bg: isDark ? "#ffffff" : "#000000",
        color: isDark ? "#000000" : "#ffffff",
      });
    } catch {
      setTooltip({ bg: "#ffffff", color: "#000000" });
    }
  };

  const handleMouseMove = (e) => {
    pos.current = { x: e.clientX, y: e.clientY };
  };

  return (
    <div className="projects__card">
      <div
        className="projects__img-wrapper"
        onMouseEnter={handleMouseEnter}
        onMouseMove={handleMouseMove}
        onMouseLeave={() => setTooltip(null)}
      >
        <img
          ref={imgRef}
          src={element.image}
          alt={element.alt}
          crossOrigin="anonymous"
        />
      </div>

      {tooltip && (
        <div
          ref={tooltipRef}
          className="projects__tooltip"
          style={{
            backgroundColor: tooltip.bg,
            color: tooltip.color,
            position: "fixed",
            top: 0,
            left: 0,
            pointerEvents: "none",
            zIndex: 999,
            transform: `translate(${current.current.x}px, ${current.current.y}px)`,
          }}
        >
          {element.title}
        </div>
      )}

      <div className="projects__title">
        <h3 className="text-h3">{element.title}</h3>
        <p className="text-small">with</p>
        <h3 className="projects__type text-h3">{element.type}</h3>
      </div>
    </div>
  );
};

const Projects = ({ items }) => {
  return (
    <section className="projects">
      <div className="projects__header">
        <p className="text-small">This is my</p>
        <h2 className="text-h2">PROJECTS</h2>
        <p className="text-small">Computer Science</p>
      </div>
      <div className="projects__grid">
        {items.map((element) => (
          <ProjectCard key={uuidv4()} element={element} />
        ))}
      </div>
    </section>
  );
};

export default Projects;
